const opType = msg.operationType || 'read';

if (opType === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

flow.set("swm_rpc_response_topic", msg.rpcResponseTopic);
flow.set("swm_write_result", msg.writeResult || null);

// Clear all parts
flow.set("swm_part_basic", null);
flow.set("swm_part_tou_times", null);
flow.set("swm_part_tou_power", null);
flow.set("swm_part_tou_voltage", null);
flow.set("swm_part_tou_capacity", null);
flow.set("swm_part_tou_charge", null);
flow.set("swm_part_reg278", null);
flow.set("swm_part_reg279", null);
flow.set("swm_part_reg291", null);

return msg;

msg.readGroup = "basic";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 241,
    quantity: 6
};
return msg;

msg.readGroup = "tou_times";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 248,
    quantity: 6
};
return msg;

msg.readGroup = "tou_power";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 254,
    quantity: 6
};
return msg;

msg.readGroup = "tou_voltage";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 260,
    quantity: 6
};
return msg;

msg.readGroup = "tou_capacity";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 266,
    quantity: 6
};
return msg;

msg.readGroup = "tou_charge";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 272,
    quantity: 6
};
return msg;

msg.readGroup = "reg278";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 278,
    quantity: 1
};
return msg;

msg.readGroup = "reg279";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 279,
    quantity: 1
};
return msg;

msg.readGroup = "reg291";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 291,
    quantity: 1
};
return msg;

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

const group = msg.readGroup;

// Export strategy mapping for register 242
const exportStrategyMap = {
    0: "selling_first",
    1: "zero_export_to_load",
    2: "zero_export_to_ct"
};

if (group === "basic") {
    // 241-246: workMode(bit field), exportStrategy, maxSell, skip, solarSell, touEnable
    const workModeReg = data[0] || 0; // 241
    const touReg = data[5] || 0; // 246
    const exportStrategyCode = data[1] || 0; // 242

    // Extract work mode from 241 Bit0-1 (10=battery first, 11=load first)
    const workModeBits = workModeReg & 0x03;
    const workModeCode = workModeBits === 0x02 ? 0 : (workModeBits === 0x03 ? 1 : 0);

    flow.set("swm_part_basic", {
        workModeCode: workModeCode,
        workModeRawValue: workModeReg,         // Store for write operations
        exportStrategyCode: exportStrategyCode, // 242 (raw value)
        exportStrategy: exportStrategyMap[exportStrategyCode] || "selling_first", // 242 (string)
        maxSellPowerW: data[2] || 0,          // 243
        solarSellEnabled: (data[4] || 0) === 1, // 245
        touEnabled: (touReg & 0x01) === 1,
        touDays: {
            monday: ((touReg >> 1) & 0x01) === 1,
            tuesday: ((touReg >> 2) & 0x01) === 1,
            wednesday: ((touReg >> 3) & 0x01) === 1,
            thursday: ((touReg >> 4) & 0x01) === 1,
            friday: ((touReg >> 5) & 0x01) === 1,
            saturday: ((touReg >> 6) & 0x01) === 1,
            sunday: ((touReg >> 7) & 0x01) === 1
        },
        touRawValue: touReg
    });
}
else if (group === "tou_times") {
    flow.set("swm_part_tou_times", data.slice(0, 6));
}
else if (group === "tou_power") {
    flow.set("swm_part_tou_power", data.slice(0, 6));
}
else if (group === "tou_voltage") {
    flow.set("swm_part_tou_voltage", data.slice(0, 6));
}
else if (group === "tou_capacity") {
    flow.set("swm_part_tou_capacity", data.slice(0, 6));
}
else if (group === "tou_charge") {
    flow.set("swm_part_tou_charge", data.slice(0, 6));
}
else if (group === "reg278") {
    const val = data[0] || 0;
    // Bit4-5: Grid peak shaving (10=disable, 11=enable)
    const gridPeakShavingEnabled = ((val >> 4) & 0x03) === 0x03;
    flow.set("swm_part_reg278", {
        rawValue: val,
        gridPeakShavingEnabled: gridPeakShavingEnabled
    });
}
else if (group === "reg279") {
    const val = data[0] || 0;
    // Bit2-3: Force off-grid (10=disable, 11=enable)
    const forceOffGrid = ((val >> 2) & 0x03) === 0x03;
    flow.set("swm_part_reg279", {
        rawValue: val,
        forceOffGrid: forceOffGrid
    });
}
else if (group === "reg291") {
    flow.set("swm_part_reg291", { limitPowerW: data[0] || 0 });
}
else {
    return null;
}

// Check if all parts received
const basic = flow.get("swm_part_basic");
const touTimes = flow.get("swm_part_tou_times");
const touPower = flow.get("swm_part_tou_power");
const touVoltage = flow.get("swm_part_tou_voltage");
const touCapacity = flow.get("swm_part_tou_capacity");
const touCharge = flow.get("swm_part_tou_charge");
const reg278 = flow.get("swm_part_reg278");
const reg279 = flow.get("swm_part_reg279");
const reg291 = flow.get("swm_part_reg291");

if (!basic || !touTimes || !touPower || !touVoltage || !touCapacity || !touCharge || !reg278 || !reg279 || !reg291) {
    return null;
}

// Helper to format time from HHMM
function formatTime(val) {
    const hh = Math.floor(val / 100);
    const mm = val % 100;
    return String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0');
}

// Build TOU slots
const slots = [];
for (let i = 0; i < 6; i++) {
    const chargeReg = touCharge[i] || 0;
    slots.push({
        slotIndex: i + 1,
        startTimeLocal: formatTime(touTimes[i] || 0),
        endTimeLocal: i < 5 ? formatTime(touTimes[i + 1] || 0) : formatTime(touTimes[0] || 0),
        allowGridCharge: (chargeReg & 0x01) === 1,
        allowGeneratorCharge: ((chargeReg >> 1) & 0x01) === 1,
        maxBatteryDischargePowerW: touPower[i] || 0,
        batteryThresholdSocPercent: touCapacity[i] || 0,
        batteryThresholdVoltageV: Math.round((touVoltage[i] || 0) * 0.01 * 100) / 100
    });
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";

const state = {
    kind: "SystemWorkModeConfigState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,

    inverterMode: {
        workModeCode: basic.workModeCode,
        exportStrategy: basic.exportStrategy,
        solarSellEnabled: basic.solarSellEnabled,
        maxSellPowerW: basic.maxSellPowerW,
        forceOffGrid: reg279.forceOffGrid
    },

    energyPriority: {
        pattern: basic.workModeCode === 0 ? "battery_first" : "load_first"
    },

    gridPeakShaving: {
        enabled: reg278.gridPeakShavingEnabled,
        limitPowerW: reg291.limitPowerW
    },

    timeOfUse: {
        enabled: basic.touEnabled,
        daysActive: basic.touDays,
        slots: slots
    }
};

// Store raw values for write operations
flow.set("swm_reg241_current", basic.workModeRawValue);
flow.set("swm_reg246_current", basic.touRawValue);
flow.set("swm_reg278_current", reg278.rawValue);
flow.set("swm_reg279_current", reg279.rawValue);

// Clear parts
flow.set("swm_part_basic", null);
flow.set("swm_part_tou_times", null);
flow.set("swm_part_tou_power", null);
flow.set("swm_part_tou_voltage", null);
flow.set("swm_part_tou_capacity", null);
flow.set("swm_part_tou_charge", null);
flow.set("swm_part_reg278", null);
flow.set("swm_part_reg279", null);
flow.set("swm_part_reg291", null);

const writeResult = flow.get("swm_write_result");
const rpcResponseTopic = flow.get("swm_rpc_response_topic");

flow.set("swm_write_result", null);
flow.set("swm_rpc_response_topic", null);

if (writeResult) {
    msg.payload = {
        success: writeResult.success,
        message: writeResult.message,
        writes: writeResult.writes,
        state: state
    };
} else {
    msg.payload = state;
}

msg.state = state;
msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;

const params = msg.rpcParams || {};
const invMode = params.inverterMode || {};
const energyPri = params.energyPriority || {};
const gridPeak = params.gridPeakShaving || {};
const tou = params.timeOfUse || {};
const touSlots = tou.slots || [];

const writes = [];

// Export strategy string to code mapping
const exportStrategyToCode = {
    "selling_first": 0,
    "zero_export_to_load": 1,
    "zero_export_to_ct": 2
};

// Register 241 - Work mode (Bit0-1: 10=battery first, 11=load first)
let needReg241Write = false;
let reg241NewValue = flow.get("swm_reg241_current") || 0;

if (invMode.workModeCode !== undefined) {
    needReg241Write = true;
    reg241NewValue = reg241NewValue & ~0x0003; // Clear bits 0-1
    if (invMode.workModeCode === 0) {
        reg241NewValue = reg241NewValue | 0x0002; // Set bits to 10 (battery first)
    } else {
        reg241NewValue = reg241NewValue | 0x0003; // Set bits to 11 (load first)
    }
} else if (energyPri.pattern !== undefined) {
    needReg241Write = true;
    reg241NewValue = reg241NewValue & ~0x0003; // Clear bits 0-1
    if (energyPri.pattern === "battery_first") {
        reg241NewValue = reg241NewValue | 0x0002; // Set bits to 10
    } else {
        reg241NewValue = reg241NewValue | 0x0003; // Set bits to 11
    }
}

if (needReg241Write) {
    writes.push({ register: 241, value: reg241NewValue, name: "Work Mode" });
}

// Export strategy (242)
if (invMode.exportStrategy !== undefined) {
    const strategyCode = exportStrategyToCode[invMode.exportStrategy];
    if (strategyCode !== undefined) {
        writes.push({ register: 242, value: strategyCode, name: "Export Strategy" });
    }
}

// Max sell power (243)
if (invMode.maxSellPowerW !== undefined) {
    writes.push({ register: 243, value: invMode.maxSellPowerW, name: "Max Sell Power" });
}

// Solar sell enable (245)
if (invMode.solarSellEnabled !== undefined) {
    writes.push({ register: 245, value: invMode.solarSellEnabled ? 1 : 0, name: "Solar Sell" });
}

// Grid peak shaving power (291)
if (gridPeak.limitPowerW !== undefined) {
    writes.push({ register: 291, value: gridPeak.limitPowerW, name: "Grid Peak Power" });
}

// Register 246 - TOU enable + days (bit field)
let needReg246Write = false;
let reg246NewValue = flow.get("swm_reg246_current") || 0;

if (tou.enabled !== undefined) {
    needReg246Write = true;
    if (tou.enabled) {
        reg246NewValue = reg246NewValue | 0x01;
    } else {
        reg246NewValue = reg246NewValue & ~0x01;
    }
}

if (tou.daysActive) {
    needReg246Write = true;
    const days = tou.daysActive;
    if (days.monday !== undefined) {
        reg246NewValue = days.monday ? (reg246NewValue | 0x02) : (reg246NewValue & ~0x02);
    }
    if (days.tuesday !== undefined) {
        reg246NewValue = days.tuesday ? (reg246NewValue | 0x04) : (reg246NewValue & ~0x04);
    }
    if (days.wednesday !== undefined) {
        reg246NewValue = days.wednesday ? (reg246NewValue | 0x08) : (reg246NewValue & ~0x08);
    }
    if (days.thursday !== undefined) {
        reg246NewValue = days.thursday ? (reg246NewValue | 0x10) : (reg246NewValue & ~0x10);
    }
    if (days.friday !== undefined) {
        reg246NewValue = days.friday ? (reg246NewValue | 0x20) : (reg246NewValue & ~0x20);
    }
    if (days.saturday !== undefined) {
        reg246NewValue = days.saturday ? (reg246NewValue | 0x40) : (reg246NewValue & ~0x40);
    }
    if (days.sunday !== undefined) {
        reg246NewValue = days.sunday ? (reg246NewValue | 0x80) : (reg246NewValue & ~0x80);
    }
}

if (needReg246Write) {
    writes.push({ register: 246, value: reg246NewValue, name: "TOU Enable+Days" });
}

// Register 278 - Grid peak shaving enable (Bit4-5: 10=disable, 11=enable)
let needReg278Write = false;
let reg278NewValue = flow.get("swm_reg278_current") || 0;

if (gridPeak.enabled !== undefined) {
    needReg278Write = true;
    reg278NewValue = reg278NewValue & ~0x0030; // Clear bits 4-5
    if (gridPeak.enabled) {
        reg278NewValue = reg278NewValue | 0x0030; // Set bits 4-5 (11)
    } else {
        reg278NewValue = reg278NewValue | 0x0020; // Set bit 5, clear bit 4 (10)
    }
}

if (needReg278Write) {
    writes.push({ register: 278, value: reg278NewValue, name: "Reg278 GridPeak" });
}

// Register 279 - Force off-grid (Bit2-3: 10=disable, 11=enable)
let needReg279Write = false;
let reg279NewValue = flow.get("swm_reg279_current") || 0;

if (invMode.forceOffGrid !== undefined) {
    needReg279Write = true;
    reg279NewValue = reg279NewValue & ~0x000C; // Clear bits 2-3
    if (invMode.forceOffGrid) {
        reg279NewValue = reg279NewValue | 0x000C; // Set bits 2-3 (11)
    } else {
        reg279NewValue = reg279NewValue | 0x0008; // Set bit 3, clear bit 2 (10)
    }
}

if (needReg279Write) {
    writes.push({ register: 279, value: reg279NewValue, name: "Force Off-Grid" });
}

// TOU Slots
for (const slot of touSlots) {
    const idx = (slot.slotIndex || 1) - 1;
    if (idx < 0 || idx > 5) continue;

    // Time point (248-253)
    if (slot.startTimeLocal !== undefined) {
        const parts = slot.startTimeLocal.split(':');
        const hhmm = parseInt(parts[0]) * 100 + parseInt(parts[1] || 0);
        writes.push({ register: 248 + idx, value: hhmm, name: `TOU Time ${idx+1}` });
    }

    // Power (254-259)
    if (slot.maxBatteryDischargePowerW !== undefined) {
        writes.push({ register: 254 + idx, value: slot.maxBatteryDischargePowerW, name: `TOU Power ${idx+1}` });
    }

    // Voltage (260-265)
    if (slot.batteryThresholdVoltageV !== undefined) {
        const volVal = Math.round(slot.batteryThresholdVoltageV * 100);
        writes.push({ register: 260 + idx, value: volVal, name: `TOU Voltage ${idx+1}` });
    }

    // Capacity (266-271)
    if (slot.batteryThresholdSocPercent !== undefined) {
        writes.push({ register: 266 + idx, value: slot.batteryThresholdSocPercent, name: `TOU Capacity ${idx+1}` });
    }

    // Charge enable (272-277)
    if (slot.allowGridCharge !== undefined || slot.allowGeneratorCharge !== undefined) {
        let chargeVal = 0;
        if (slot.allowGridCharge) chargeVal |= 0x01;
        if (slot.allowGeneratorCharge) chargeVal |= 0x02;
        writes.push({ register: 272 + idx, value: chargeVal, name: `TOU Charge ${idx+1}` });
    }
}

if (writes.length === 0) {
    msg.operationType = 'read';
    return [null, msg];
}

// Store to GLOBAL context
global.set("swm_write_queue", writes);
global.set("swm_write_index", 0);
global.set("swm_write_results", []);
global.set("swm_write_rpc_topic", msg.rpcResponseTopic);

node.status({ fill: "blue", shape: "dot", text: `${writes.length} writes queued` });

return [msg, null];

const writes = global.get("swm_write_queue") || [];
const index = global.get("swm_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

const newMsg = {
    payload: {
        fc: 16,
        unitid: 1,
        address: current.register,
        quantity: 1,
        value: [current.value]
    },
    currentWrite: current,
    writeIndex: index
};

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return newMsg;

const writes = global.get("swm_write_queue") || [];
let index = global.get("swm_write_index") || 0;
const results = global.get("swm_write_results") || [];

// Check if this is just a confirmation (has address and length but no error)
const isConfirmation = msg.payload && 
                       msg.payload.address !== undefined && 
                       msg.payload.length !== undefined &&
                       !msg.payload.error;

if (isConfirmation) {
    // This is the write confirmation from output 2 - ignore it
    return null;
}

const current = writes[index];
if (current) {
    results.push({ 
        register: current.register, 
        name: current.name, 
        value: current.value, 
        success: true 
    });
    global.set("swm_write_results", results);
}

index++;
global.set("swm_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current ? current.name : 'Unknown'} OK` });

if (index < writes.length) {
    return [{ doNext: true }, null];
}

const rpcTopic = global.get("swm_write_rpc_topic");

global.set("swm_write_queue", null);
global.set("swm_write_index", null);
global.set("swm_write_rpc_topic", null);

const finalMsg = {
    writeResult: {
        success: true,
        message: `Successfully wrote ${results.length} register(s)`,
        writes: results
    },
    rpcResponseTopic: rpcTopic
};

node.status({ fill: "green", shape: "dot", text: `All ${results.length} writes OK!` });

return [null, finalMsg];
